import os
import random
import zlib
from typing import List

# We generate arbitrary binary data up to 1024 bytes (as fuzzer caps src_size to <=1024)
# Aim: produce inputs that exercise different compression behaviors: highly compressible,
# moderately compressible, incompressible, small/empty, repetitive with varying periods,
# structured patterns, and randomized sizes. No external deps; deterministic with seed.

_MAX_SRC = 1024

def _rand(r: random.Random, n: int) -> bytes:
    return bytes(r.getrandbits(8) for _ in range(n))

def _repeat_byte(r: random.Random, length: int) -> bytes:
    return bytes([r.randrange(256)]) * length

def _ramp(length: int, start: int = 0, step: int = 1) -> bytes:
    buf = bytearray(length)
    v = start & 0xFF
    for i in range(length):
        buf[i] = v
        v = (v + step) & 0xFF
    return bytes(buf)

def _toggle_pattern(length: int, a: int, b: int, run_a: int, run_b: int) -> bytes:
    out = bytearray()
    cur = a
    run = run_a
    while len(out) < length:
        take = min(run, length - len(out))
        out.extend([cur] * take)
        if cur == a:
            cur = b
            run = run_b
        else:
            cur = a
            run = run_a
    return bytes(out)

def _periodic_pattern(length: int, period: int, base: int) -> bytes:
    # Create a repeating block with slight variation within period
    block = bytearray(period)
    for i in range(period):
        block[i] = (base + i * 37) & 0xFF
    reps, rem = divmod(length, period)
    return bytes(block) * reps + bytes(block[:rem])

def _palindrome_block(r: random.Random, length: int) -> bytes:
    half = (length + 1) // 2
    left = _rand(r, half)
    if length % 2 == 0:
        return left + left[::-1]
    else:
        return left[:-1] + left[::-1]

def _structured_mix(r: random.Random, length: int) -> bytes:
    # Mix of segments: zeros, random, ramp, periodic, toggles
    parts: List[bytes] = []
    remaining = length
    generators = [
        lambda n: _repeat_byte(r, n),
        lambda n: _rand(r, n),
        lambda n: _ramp(n, start=r.randrange(256), step=r.randrange(1, 17)),
        lambda n: _periodic_pattern(n, period=max(1, r.randrange(1, 33)), base=r.randrange(256)),
        lambda n: _toggle_pattern(n, a=r.randrange(256), b=r.randrange(256), run_a=max(1, r.randrange(1, 129)), run_b=max(1, r.randrange(1, 129))),
        lambda n: _palindrome_block(r, n),
    ]
    while remaining > 0:
        seg_len = min(remaining, max(1, int(r.paretovariate(2)) % 256))
        gen = r.choice(generators)
        parts.append(gen(seg_len))
        remaining -= seg_len
    return b"".join(parts)

def _compressibility_hint(data: bytes) -> float:
    # Use zlib as a heuristic to categorize compressibility; this does not need to match blz
    if not data:
        return 0.0
    try:
        comp = zlib.compress(data, level=6)
        return len(comp) / max(1, len(data))
    except Exception:
        return 1.0

def _choose_length(r: random.Random) -> int:
    # Bias towards small lengths but include large values up to 1024
    choices = [0, 1, 2, 3, 4, 7, 8, 15, 16, 31, 32, 63, 64, 127, 128, 255, 256, 511, 512, 768, 1023, 1024]
    if r.random() < 0.6:
        return r.choice(choices)
    return r.randrange(0, _MAX_SRC + 1)

def generate(seed: int) -> bytes:
    r = random.Random(seed)

    length = _choose_length(r)

    # Select a profile to produce different behavior for compression
    profile = r.randrange(0, 10)

    if length == 0:
        return b""

    if profile == 0:
        # All zeros
        data = bytes([0]) * length
    elif profile == 1:
        # Single repeated random byte
        data = _repeat_byte(r, length)
    elif profile == 2:
        # Short-period pattern
        period = max(1, r.randrange(1, 17))
        data = _periodic_pattern(length, period, r.randrange(256))
    elif profile == 3:
        # Long runs toggling
        data = _toggle_pattern(length, a=r.randrange(256), b=r.randrange(256), run_a=max(1, r.randrange(16, 256)), run_b=max(1, r.randrange(16, 256)))
    elif profile == 4:
        # Incrementing ramp
        data = _ramp(length, start=r.randrange(256), step=max(1, r.randrange(1, 8)))
    elif profile == 5:
        # Random noise (likely incompressible)
        data = _rand(r, length)
    elif profile == 6:
        # Mix of segments
        data = _structured_mix(r, length)
    elif profile == 7:
        # Palindromic (self-similarity)
        data = _palindrome_block(r, length)
    elif profile == 8:
        # Header-like prefix + body: emulate file-like structure
        prefix_len = min(length, r.choice([0, 2, 4, 8, 16]))
        prefix = bytes([ord('B'), ord('L'), ord('Z'), r.randrange(256)])[:prefix_len]
        body_len = length - len(prefix)
        body = _structured_mix(r, body_len) if body_len > 0 else b""
        data = prefix + body
    else:
        # Skewed: mostly zeros with sparse random bytes
        data = bytearray(bytes([0]) * length)
        flips = r.randrange(0, max(1, length // 16 + 1))
        for _ in range(flips):
            idx = r.randrange(length)
            data[idx] = r.randrange(256)
        data = bytes(data)

    # Ensure size bound (<= 1024) satisfied and return bytes
    if len(data) > _MAX_SRC:
        data = data[:_MAX_SRC]

    # Optionally, nudge edge sizes for coverage
    if r.random() < 0.2:
        # Adjust to interesting boundary lengths if close
        targets = [0, 1, 2, 3, 7, 8, 15, 16, 31, 32, 63, 64, 127, 128, 255, 256, 511, 512, 1023, 1024]
        t = r.choice(targets)
        if t <= _MAX_SRC:
            if t > len(data):
                data = data + _rand(r, t - len(data))
            elif t < len(data):
                data = data[:t]

    # Keep it valid arbitrary binary; no further mutation
    return data
